#include <vector>
#include <complex>
#include <cmath>
#include <algorithm>
#include <cstddef>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel stable merge sort using an auxiliary buffer.
    std::vector<std::complex<double>> tmp(n);

    auto mag2 = [](const std::complex<double>& z) -> double {
        // Compare by squared magnitude to avoid sqrt; preserves ordering.
        return std::norm(z);
    };

    // Start with x as the source, tmp as the destination. Each pass merges runs of size 'width'.
    // We swap roles after each pass.
    const std::complex<double>* src = x.data();
    std::complex<double>* dst = tmp.data();

    for (std::size_t width = 1; width < n; width *= 2) {
        // Merge [i, i+width) and [i+width, i+2*width) for i = 0, 2*width, 4*width, ...
        // Each merge writes to a disjoint range in dst -> safe without atomics/critical.
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t ii = 0; ii < static_cast<std::ptrdiff_t>(n); ii += static_cast<std::ptrdiff_t>(2 * width)) {
            const std::size_t i = static_cast<std::size_t>(ii);
            const std::size_t left  = i;
            const std::size_t mid   = std::min(i + width, n);
            const std::size_t right = std::min(i + 2 * width, n);

            std::size_t a = left;
            std::size_t b = mid;
            std::size_t k = left;

            // Stable merge: if equal magnitude, keep original order by taking from left run first.
            while (a < mid && b < right) {
                const double ma = mag2(src[a]);
                const double mb = mag2(src[b]);
                if (ma <= mb) {
                    dst[k++] = src[a++];
                } else {
                    dst[k++] = src[b++];
                }
            }
            while (a < mid)  dst[k++] = src[a++];
            while (b < right) dst[k++] = src[b++];
        }

        // Swap src/dst for next pass.
        if (src == x.data()) {
            src = tmp.data();
            dst = x.data();
        } else {
            src = x.data();
            dst = tmp.data();
        }
    }

    // If the final sorted data ended up in tmp, copy back to x.
    if (src == tmp.data()) {
        std::copy(tmp.begin(), tmp.end(), x.begin());
    }
}
